  2:{'filas-proporcionales':rng=>{const f=vecAl(rng,2,6).map(x=>x||1),k=rng.elegir([2,3,-1,-2]),A=[f,f.map(x=>k*x)];return numRes(`Calcula \\(\\det ${mat(A)}\\)`,0,'0',[paso('La fila 2 es '+k+' veces la fila 1',`\\(${vec(A[1])} = ${k}\\cdot${vec(f)}\\)`,'Filas proporcionales.'),final('Determinante cero',`\\(${c(0)}\\)`,'Filas proporcionales ⇒ det = 0.','0')],[malNum(f[0]*A[1][1]+f[1]*A[1][0],'ad − bc: se resta.'),malNum(k,'No es el factor.'),malNum(f[0]*A[1][1],'Falta restar bc.')].filter(e=>e.valor!=='0'),()=>det2(A)===0)},
     'k-singular':rng=>{const a=rng.noCero(-5,5),b=rng.noCero(-5,5),m=rng.elegir([2,3,-2]),cc=a*m,k=b*m;return numRes(`¿Para qué k es 0 el determinante de \\(${mat([[a,b],[cc,'k']])}\\)?`,k,`k = ${k}`,[paso('ad − bc = 0',`\\(${a}k - ${par(b)}\\cdot${par(cc)} = 0\\)`,'Plantea.'),final('Despeja',`\\(k = ${c(k)}\\)`,'Matriz singular (sin inversa).',`k = ${k}`)],[malNum(-k,'Revisa el signo.'),malNum(b*cc,'Divide entre '+a+'.'),malNum(0,'Con k = 0 no da 0.')].filter(e=>e.valor!==String(k)),()=>a*k-b*cc===0)}},
  3:{'escalar-det':rng=>{const d=rng.noCero(-8,8),k=rng.elegir([2,3,-1,-2]),n=rng.elegir([2,3]),r=k**n*d;return numRes(`Si A es ${n}×${n} y \\(\\det A = ${d}\\), ¿cuánto vale \\(\\det(${k}A)\\)?`,r,String(r),[paso('Cada fila se multiplica por '+k,`\\(\\det(${k}A) = ${k}^{${n}}\\det A\\)`,`Son ${n} filas.`),final('Calcula',`\\(${k**n}\\cdot${par(d)} = ${c(r)}\\)`,'kⁿ, no k.',String(r))],[malNum(k*d,`Es ${k}^${n}, no ${k}.`),malNum(k*n*d,'Es potencia, no producto.'),malNum(d,'El escalar sí cambia el det.')].filter(e=>e.valor!==String(r)),()=>{const A=n===2?[[d,0],[0,1]]:[[d,0,0],[0,1,0],[0,0,1]],K=A.map(f=>f.map(x=>k*x));return (n===2?det2(K):det3(K))===r})},
     'producto':rng=>{const a=rng.noCero(-6,6),b=rng.noCero(-6,6),r=a*b;return numRes(`Si \\(\\det A = ${a}\\) y \\(\\det B = ${b}\\), ¿cuánto vale \\(\\det(AB)\\)?`,r,String(r),[paso('Propiedad',`\\(\\det(AB) = \\det A\\cdot\\det B\\)`,'El determinante del producto es el producto.'),final('Calcula',`\\(${c(r)}\\)`,'Así de simple.',String(r))],[malNum(a+b,'Se multiplican.'),malNum(-r,'Revisa signos.'),malNum(a*a*b*b,'Solo una vez cada uno.')].filter(e=>e.valor!==String(r)),()=>det2(mulMM([[a,0],[0,1]],[[b,0],[0,1]]))===r)}},
