const general=n=>rng=>{const d=n<=2?2:3,R=n<=3?4:6,X=vecAl(rng,d,n<=3?5:8);let A;do A=Array.from({length:d},()=>vecAl(rng,d,R));while(!inv(A)||!A[0][0]);return gaussRes(A,X)};
